// app/Policies/OrderPolicy.php
class OrderPolicy
{
    public function before(User $user, string $ability): ?bool
    {
        return $user->isSuperAdmin() ? true : null;       // null = fall through to the specific method
    }
    public function view(User $user, Order $order): bool
    {
        return $order->user_id === $user->id || $user->hasPermissionTo('orders.view-any');
    }
    public function update(User $user, Order $order): Response
    {
        return $order->user_id === $user->id && $order->status === 'draft'
            ? Response::allow()
            : Response::deny('Only draft orders can be edited by their owner.');
    }
}

