// OrderPolicy
public function view(User $u, Order $o): bool { return $o->user_id === $u->id || $u->role === 'admin'; }
public function update(User $u, Order $o): bool { return $o->user_id === $u->id && $o->status === 'pending'; }

// routes/api.php
Route::middleware('auth:sanctum')->prefix('v1')->group(function () {
    Route::get('/orders/{order}', [OrderController::class, 'show'])->middleware('can:view,order');
    Route::patch('/orders/{order}', [OrderController::class, 'update'])->middleware('can:update,order');
});

// tests/Feature/OrderAuthorizationTest.php
public function test_owner_can_view(): void {
    $order = Order::factory()->create();
    Sanctum::actingAs($order->user);
    $this->getJson("/api/v1/orders/{$order->id}")->assertOk();
}
public function test_other_user_forbidden(): void {
    $order = Order::factory()->create();
    Sanctum::actingAs(User::factory()->create());
    $this->getJson("/api/v1/orders/{$order->id}")->assertForbidden();
}
public function test_admin_can_view(): void {
    $order = Order::factory()->create();
    Sanctum::actingAs(User::factory()->create(['role' => 'admin']));
    $this->getJson("/api/v1/orders/{$order->id}")->assertOk();
}
public function test_guest_unauthenticated(): void {
    $order = Order::factory()->create();
    $this->getJson("/api/v1/orders/{$order->id}")->assertUnauthorized();
}

